            console.log('📅 Car years loaded:', window.carYears);

            // OVERRIDE - Direct manufacturer click handler
            $(document).on('click', '.manufacturer-item', function(e) {
                e.preventDefault();
                e.stopPropagation();

                const manufacturer = $(this).text().trim();
                console.log('🎯 Clicked manufacturer:', manufacturer);

                // ✅ Sử dụng window.carModels thay vì carModels
                const models = window.carModels[manufacturer] || [];
                console.log('📦 Models:', models);

                if (models.length === 0) {
                    $('#manufacturer-models-container').html(
                        '<div class="alert alert-info">Không có mẫu xe</div>');
                } else {
                    let html = '';
                    models.forEach(m => {
                        html +=
                            `<div class="search-widget-popup-item model-item" data-value="${m}">${m}</div>`;
                    });
                    $('#manufacturer-models-container').html(html);
                }

                // Show step 2
                $('#search-widget-type .search-widget-list').addClass('d-none');
                $('#search-widget-type .search-widget-list[data-step-target="2"]').removeClass('d-none');
                $('#search-widget-type .search-widget-popup-title').removeClass('active');
                $('#search-widget-type .search-widget-popup-title[data-step="2"]').addClass('active');

                console.log('✅ Step 2 shown');
            });

            // Model click handler
            $(document).on('click', '.model-item', function(e) {
                e.preventDefault();
                const model = $(this).text().trim();
                console.log('🎯 Clicked model:', model);

                // ✅ Sử dụng window.carModels và window.carYears
                const manufacturer = Object.keys(window.carModels).find(m => window.carModels[m].includes(
                    model));
                const years = (window.carYears[manufacturer] && window.carYears[manufacturer][model]) || [];

                // ✅ Nếu không có năm, tự động search với manufacturer + model
                if (years.length === 0) {
                    console.log('⚠️ No years available, performing search with manufacturer + model');

                    // Đóng modal
                    const searchWidgetType = typeof bootstrap !== "undefined" && bootstrap.Modal ?
                        bootstrap.Modal.getInstance(document.getElementById("search-widget-type")) :
                        null;
                    if (searchWidgetType) {
                        searchWidgetType.hide();
                    }

                    // Tự động search với manufacturer + model (không có năm)
                    const searchQuery = `Thương hiệu: ${manufacturer}, Mẫu xe: ${model}`;
                    console.log('🔍 Auto search:', searchQuery);

                    // Trigger search (giống như khi click vào year-item)
                    // Bạn cần gọi hàm search tương ứng ở đây
                    // Ví dụ: performSearch(searchQuery, 'car');

                    // Hoặc nếu có hàm search riêng, gọi nó:
                    if (typeof performSearch === 'function') {
                        performSearch(searchQuery, 'car');
                    } else {
                        // Fallback: Hiển thị thông báo
                        alert(`Không có đời xe cho ${manufacturer} ${model}. Đang tìm kiếm...`);
                        // Có thể trigger search form submit hoặc AJAX call ở đây
                    }

                    return;
                }

                // Nếu có năm, hiển thị danh sách năm như bình thường
                let html = '';
                years.forEach(y => {
                    html +=
                        `<div class="search-widget-popup-item year-item" data-value="${y}">${y}</div>`;
